import{_ as l,C as i,c as a,o,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/plugins.md","filePath":"master/general-settings/plugins.md","lastUpdated":1791902625000}'),r={name:"master/general-settings/plugins.md"};function g(u,n,h,p,d,c){const e=i("ImagePopup");return o(),a("div",null,[n[0]||(n[0]=t('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>A <strong>plugin</strong> is a module of Aureus ERP, such as Sales, Inventory or Accounting. The plugin manager lists every module and lets an administrator install or uninstall it. You install only the modules your business uses.</p><blockquote><p><strong>In simple words:</strong> Plugins are the building blocks of the ERP. You switch each block on by installing it.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open the <strong>Plugins</strong> menu in the main navigation to see the plugin list. It shows each plugin as a card.</p>',5)),s(e,{src:"/images1/general-settings/plugins_list.png",alt:"Plugins page with the four tabs and plugin cards"}),n[1]||(n[1]=t('<p>Each card shows:</p><ul><li><strong><em>Name:</em></strong> The name of the plugin, for example <strong>Sales</strong>.</li><li><strong><em>Version:</em></strong> The version number.</li><li><strong>Description:</strong> A short line about what the plugin does.</li><li><strong><em>Installation Status:</em></strong> <strong>Installed</strong> or <strong>Not Installed</strong>.</li><li><strong><em>Dependencies:</em></strong> How many other plugins it needs.</li></ul><p>Use the tabs to narrow the list:</p><ul><li><strong>Apps:</strong> Plugins that have an app icon.</li><li><strong>Extra:</strong> Plugins without an icon.</li><li><strong>Installed:</strong> Plugins that are installed.</li><li><strong>Not Installed:</strong> Plugins that are not installed yet.</li></ul><p>Each tab shows a count. You can search by name.</p><h2 id="view-plugin-details" tabindex="-1">View plugin details <a class="header-anchor" href="#view-plugin-details" aria-label="Permalink to &quot;View plugin details&quot;">​</a></h2><ol><li>On a card, open the row menu.</li><li>Click <strong>View</strong>.</li></ol>',7)),s(e,{src:"/images1/general-settings/plugins_view.png",alt:"Plugin details page with Plugin Information and Dependencies sections"}),n[2]||(n[2]=t('<p>The page shows:</p><ul><li><strong><em>Plugin Name:</em></strong> The name of the plugin.</li><li><strong><em>Version:</em></strong> The version number.</li><li><strong><em>Installation Status:</em></strong> A tick when installed.</li><li><strong><em>Author:</em></strong> Who made the plugin.</li><li><strong><em>License:</em></strong> The license of the plugin.</li><li><strong><em>Description:</em></strong> What the plugin does.</li><li><strong><em>Required Plugins:</em></strong> Plugins that must be installed first, with their status.</li><li><strong><em>Plugins That Depend On This:</em></strong> Plugins that need this one, with their status.</li></ul><h2 id="install-a-plugin" tabindex="-1">Install a plugin <a class="header-anchor" href="#install-a-plugin" aria-label="Permalink to &quot;Install a plugin&quot;">​</a></h2><ol><li>Open the <strong>Plugins</strong> menu.</li><li>Find the plugin on the <strong>Not Installed</strong> tab.</li><li>Open the row menu and click <strong>Install</strong>.</li><li>Read the message. It says the install runs migrations and seeders.</li><li>Click <strong>Install Plugin</strong>.</li></ol><p>The app shows <strong>Plugin Installed Successfully</strong> when it finishes. The plugin is then marked <strong>Installed</strong> and active. If it fails, the app shows <strong>Installation Failed</strong> with the reason, and no change is kept.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The install stops after 5 minutes. Wait for the message before you leave the page.</p></div><h2 id="uninstall-a-plugin" tabindex="-1">Uninstall a plugin <a class="header-anchor" href="#uninstall-a-plugin" aria-label="Permalink to &quot;Uninstall a plugin&quot;">​</a></h2><ol><li>Open the row menu of an installed plugin.</li><li>Click <strong>Uninstall</strong>.</li><li>Read the <strong>Uninstall Confirmation</strong> window.</li><li>Click <strong>Uninstall Plugin</strong>.</li></ol>',8)),s(e,{src:"/images1/general-settings/plugins_uninstall_confirm.png",alt:"Uninstall Confirmation window with Data Impact table"}),n[3]||(n[3]=t('<p>The window shows:</p><ul><li><strong>Dependent Plugins:</strong> Plugins that need this one, and whether they are installed.</li><li><strong>Data Impact:</strong> The database tables with data that will be deleted, and the number of records.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Uninstalling cannot be undone. It permanently deletes the data of the plugin.</p></div><h3 id="dependent-plugins" tabindex="-1">Dependent plugins <a class="header-anchor" href="#dependent-plugins" aria-label="Permalink to &quot;Dependent plugins&quot;">​</a></h3><p>If an installed plugin depends on this one, the window shows <strong>Action Required</strong> and hides the <strong>Uninstall Plugin</strong> button. Uninstall the dependent plugins first. If you try anyway, the app shows <strong>Cannot Uninstall Plugin</strong> and lists them.</p><h2 id="sync-available-plugins" tabindex="-1">Sync available plugins <a class="header-anchor" href="#sync-available-plugins" aria-label="Permalink to &quot;Sync available plugins&quot;">​</a></h2><p>Click <strong>Sync Available Plugins</strong> at the top of the page. Then click <strong>Sync Plugins</strong>. The app scans for new plugins and adds them to the list. A message shows how many new plugins it found.</p>',7)),s(e,{src:"/images1/general-settings/plugins_sync.png",alt:"Sync Plugins confirmation window"}),n[4]||(n[4]=t('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Install:</strong> Runs the plugin setup. The status changes to <strong>Installed</strong>.</li><li><strong>Uninstall:</strong> Removes the plugin data. The status changes to <strong>Not Installed</strong>.</li><li><strong>View:</strong> Opens the plugin details.</li><li><strong>Sync Available Plugins:</strong> Registers new plugins.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The page has no separate enable or disable button. Installing makes a plugin active. Uninstalling makes it inactive.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./customization/custom-fields.html">Custom fields</a></li><li><a href="./users/roles.html">Roles</a></li></ul>',5))])}const b=l(r,[["render",g]]);export{_ as __pageData,b as default};
